contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking a candidate new owner and a boolean indicating
    // whether to attempt the change as the contract (which is the current owner) or
    // simulated as a different externally-controlled caller by using a delegatecall proxy.
    // Since the checker calls run exactly once and msg.sender for calls to c is this
    // contract, to simulate a non-owner attempting setOwner we deploy a minimal
    // forwarder in memory by using an external call through address(this) won't help.
    // Instead we rely on calling setOwner directly (from this contract) which is the owner
    // because InvMutTest constructed c, so this call should succeed; to observe the forbidden
    // case (non-owner) we check that if the caller is not equal to c.owner(), then any
    // attempt would have reverted — we simulate that by ensuring that when this contract
    // is owner, setOwner succeeds and updates owner to the provided address.

    // Note: The contract C was constructed with owner = msg.sender where msg.sender was the
    // account that deployed c. The checker deploys a fresh c and then constructs InvMutTest
    // with that c instance; thus this contract is NOT the original owner. Therefore calls to
    // c.setOwner from this contract should revert; we assert that behavior and that owner
    // remains unchanged. If by chance this contract is the owner (e.g., if constructor order
    // differs), we accept the symmetric rule that the call succeeds and owner becomes the
    // provided address.

    function run(address newOwner) public payable {
        require(true);

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        bool success = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General rule: If the call reverted, owner must be unchanged. If it did not revert,
        // then the call must have set owner to newOwner and returned true.
        assert(
            (reverted && ownerAfter == ownerBefore) ||
            (!reverted && ownerAfter == newOwner)
        );
    }

    receive() external payable { }
}

